\usetikzlibrary{decorations.markings}
\tikzset{midarrow/.style={decoration={markings,mark=at position 0.55 with {\arrow{>}}},postaction={decorate}}}
\coordinate (R) at (4.8,1.5);\coordinate (P) at (2.4,3);\coordinate (Q) at (2.4,0);\coordinate (T) at (0,1.5);
\draw[midarrow] (R)--(P) node[pos=0.35,above right] {$16$};
\draw[midarrow] (R)--(Q) node[pos=0.35,below right] {$12$};
\draw[midarrow] (P)--(Q) node[pos=0.35,right] {$5$};
\draw[midarrow] (P)--(T) node[pos=0.35,above left] {$10$};
\draw[midarrow] (Q)--(T) node[pos=0.35,below left] {$14$};
\fill[black] (R) circle (2pt) node[right] {$R$};
\fill[black] (P) circle (2pt) node[above] {$P$};
\fill[black] (Q) circle (2pt) node[below] {$Q$};
\fill[black] (T) circle (2pt) node[left] {$T$};
\end{tikzpicture}[/tikz]

