Compare each row with the edges already drawn. Rows $S$ and $B$ are complete. Row $T$ requires no outgoing edge.
Row $A$ requires $A\to B$ with capacity $6$ and $A\to T$ with capacity $15$. Add these two labelled edges with arrows pointing towards $B$ and $T$.
[tikz]\begin{tikzpicture}[draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\usetikzlibrary{decorations.markings}
\tikzset{midarrow/.style={decoration={markings,mark=at position 0.55 with {\arrow{>}}},postaction={decorate}}}
\coordinate (S) at (0,1.5);\coordinate (A) at (2.4,3);\coordinate (B) at (2.4,0);\coordinate (T) at (4.8,1.5);
\draw[midarrow] (S)--(A) node[pos=0.35,above left] {$18$};
\draw[midarrow] (S)--(B) node[pos=0.35,below left] {$13$};
\draw[midarrow] (B)--(T) node[pos=0.35,below right] {$17$};
\draw[midarrow] (A)--(B) node[pos=0.35,right] {$6$};
\draw[midarrow] (A)--(T) node[pos=0.35,above right] {$15$};
\fill[black] (S) circle (2pt) node[left] {$S$};
\fill[black] (A) circle (2pt) node[above] {$A$};
\fill[black] (B) circle (2pt) node[below] {$B$};
\fill[black] (T) circle (2pt) node[right] {$T$};
\end{tikzpicture}[/tikz]
